// TH18 v1.00a Stage 2 道中 第1波 th18_s2_w01.
// Source: st02.ecl.txt:1104-1133 MainSub00 + async MainSub00b.
// Closure: GirlRedA01/GirlBlueA01 (933-942 / 511-520) call GirlA01 (131-151),
// and its async GirlA01_at (152-191).
// Source frame 0 = phase timer start; the whole wave is delayed by a 120f opening buffer.
const TIME_LIMIT: int = 1100;
const TH18_RICE: int = 480; // type8, base row 352+8*16; source etSprite(0,8,6).

// Shell: extra control enemy at (0,0) carries the phase, body collision off.
// Real A01 enemies keep their source hit/hurt judgement and invulnerability.
async sub wave_holder() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_hurtbox(0fx);
    set_hitbox(0fx);
    phase_begin(0, wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

// Source MainSub00b async: one extra creation context, first run one frame after the call.
async sub girls_right() {
    for i in 0..6 {
        var u: fx = (rand(65536)-32768) as fx / 32768; // RANDF2: signed [-1,1)
        _ = spawn_enemy(224fx+u*64fx, -48fx, 140, 0, 0, 0, girl_a01);
        wait(15);
        u = (rand(65536)-32768) as fx / 32768; // Source samples each enmCreate separately.
        _ = spawn_enemy(224fx+u*64fx, -48fx, 140, 0, 0, 0, girl_a01);
        wait(15);
    }
}

// Source MainSub00 synchronous: 6 rounds, two creations 15f apart, trailing wait15.
sub girls_left() {
    for i in 0..6 {
        var u: fx = (rand(65536)-32768) as fx / 32768;
        _ = spawn_enemy(-224fx+u*64fx, -48fx, 140, 0, 0, 0, girl_a01);
        wait(15);
        u = (rand(65536)-32768) as fx / 32768;
        _ = spawn_enemy(-224fx+u*64fx, -48fx, 140, 0, 0, 0, girl_a01);
        wait(15);
    }
}

async sub wave() {
    wait(120); // opening buffer: no source motion/fire before this point
    spawn girls_right();
    girls_left();
}

// Source GirlA01 (131-151). Spawn position given by enmCreate, so FINAL_X/Y = $self_*.
async sub girl_a01() {
    set_hurtbox(12fx); // source setHurtbox(24,24), radius 12
    set_hitbox(8fx);   // source setHitbox(16,16), radius 8
    set_invuln(65535);
    // Source getAngle(%A,%FINAL_X,%FINAL_Y,0,300): head for (0,300), speed 3.3.
    move_vel(0, atan2(300fx-$self_y, 0fx-$self_x), 3.3fx, EASE_LINEAR);
    spawn girl_a01_shot();
    wait(60);
    // Source 140-141: speed 3.3->0.2 (mode1) and turn to ANGLE_PLAYER+pi
    // plus RANDF2*0.34906584rad(20deg), both starting at source t60.
    move_speed(60, 0.2fx, EASE_QUAD_IN);
    var ju: fx = (rand(65536)-32768) as fx / 32768;
    var jb: int = (ju*3641fx) as int; // 0.34906584rad nearest BAM
    move_angle(60, aim_player()+180deg+(jb as angle), EASE_QUAD_IN);
    wait(60);
    move_speed(120, 1.8fx, EASE_QUAD_IN); // Source 143.
    loop { wait(1000); }                  // Source 145-148.
}

// Source GirlA01_at (152-191). One aimed bullet per etOn; rank count/wait/speed.
async sub girl_a01_shot() {
    var rank: int = global(GVAR_RANK);
    wait(rand(60)); // Source wait(0+($RAND%60)) before etNew.
    var speed: fx = 1.5fx;
    var count: int = 1;
    var dist: fx = -6fx;
    if rank == 2 { speed = 2.6fx; count = 8; dist = -10.4fx; }
    if rank == 3 { speed = 4fx; count = 100; dist = -16fx; }
    sh_reset(0);
    sh_sprite(0, TH18_RICE, 6);  // Source etSprite(0,8,6)
    sh_aim(0, 1);                // Source etAim(0,0), aimed fan
    sh_ring(0, 0);               // fan, not ring
    sh_count(0, 1, 1);           // Source etCount(0,1,1): one way, one layer
    sh_angle(0, 0deg, 3deg);     // Source etAngle(0,0,0.05235988)
    sh_speed(0, speed, 0fx);     // M=1: only s0 is used
    // Source etEx(0,0,2,1,...) is the birth ANIM; animation omitted by policy but its
    // -4*initial-speed displacement is kept per bullet angle.
    sh_dist(0, dist);
    // Source diffI($A,1,1,8,100) do-while; Easy/Normal count 1, Hard 8, Lunatic 100.
    for i in 0..count {
        var fire_it: int = 1;
        // Source unless(($DIFF>=1)||(($RAND%3)==0)): only Easy consumes RAND and may skip.
        if rank == 0 && rand(3) != 0 { fire_it = 0; }
        if fire_it != 0 { sh_fire(0); }
        if rank == 3 { wait(20); } else { wait(30); } // Source LO20 / others30
    }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, wave_holder);
    loop { wait(600); }
}
